local SystemInfos = require(game.ReplicatedStorage._robloxManifest.LuaSystems)
local cache = {}

return function()
	local info = debug.info(4, "s")
	if cache[info] then
		return cache[info]
	end
	for k, v in SystemInfos do
		-- if info start with k
		if string.find("game." .. info, k, 1, true) then
			cache[info] = `[{v.Name}]`
			return cache[info]
		end
	end

	warn(string.format("未找到路径从属的系统名称: %s", info))
end
